    const { result } = await apply(profile, claim, { control: cancel }); expect(result).toMatchObject({ outcome: 'rolled-back', fact: { rollbackAcknowledged: true, commitMayHaveBeenSent: false } }); expect(processes.flatMap(process => process.sent).some(message => message.kind === 'execute' && message.sql === claim.compiled.steps.find(step => step.role === 'final-copy')!.sql)).toBe(false); expect(schema(profile)).toEqual(oldSchema); expect(typed(profile)).toEqual(before); noPrivateObjects(profile);
